INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginnt eine Unique Local-Adresse immer mit FC00::/7?', 2, '[{"text": "Ja", "correct": true, "because": "Standard für private Netze"}, {"text": "Nein", "correct": false, "because": "Festgelegt im Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits sind bei FC00::/7 für den Präfix reserviert?', 3, '[{"text": "7", "correct": true, "because": "/7 definiert die ersten 7 Bits"}, {"text": "64", "correct": false, "because": "Typisch für Interface-ID"}, {"text": "48", "correct": false, "because": "Typisch für Subnetze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Zweck hat eine Adresse wie FD00::1?', 4, '[{"text": "Private Netzwerke", "correct": true, "because": "Nicht global routbar"}, {"text": "Internet-Kommunikation", "correct": false, "because": "Nur lokal nutzbar"}, {"text": "Multicast-Gruppen", "correct": false, "because": "Anderer Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FC00::/7 ist nicht routbar. b) FD00:: ist lokal eindeutig.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Nicht global routbar, lokal unik"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von FC00::/7?', 5, '[{"text": "Globale Routbarkeit", "correct": true, "because": "Nur für private Netze"}, {"text": "Präfix FC00", "correct": false, "because": "Definiert Typ"}, {"text": "Subnetz-ID", "correct": false, "because": "Teil der Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Unique Local-Adressen automatisch generiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Zuweisung üblich"}, {"text": "Ja", "correct": false, "because": "Nicht wie Link-Local"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für ein privates Netz?', 3, '[{"text": "FD00::1", "correct": true, "because": "Unique Local-Bereich"}, {"text": "2001:db8::1", "correct": false, "because": "Global Unicast"}, {"text": "FE80::1", "correct": false, "because": "Link-Local"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat FC00::/7?', 5, '[{"text": "Nicht global routbar", "correct": true, "because": "Für private Nutzung"}, {"text": "Lokal eindeutig", "correct": true, "because": "Zufällige 40-Bit-ID"}, {"text": "Internet-zugänglich", "correct": false, "because": "Nicht routbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) FD00::/8 ist für private Netze. b) FC00::/7 ist global eindeutig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nur lokal unik"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Unique Local-Adresse?', 4, '[{"text": "Präfix FC00::/7", "correct": false, "because": "Definiert Typ"}, {"text": "Zufällige ID", "correct": false, "because": "Sichert Eindeutigkeit"}, {"text": "Globale Registrierung", "correct": true, "because": "Nicht öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind FC00::/7-Adressen weltweit eindeutig?', 2, '[{"text": "Nein", "correct": true, "because": "Nur lokal unik"}, {"text": "Ja", "correct": false, "because": "Keine globale Garantie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei FD00::1 essenziell?', 4, '[{"text": "Präfix FD00", "correct": true, "because": "Teil von FC00::/7"}, {"text": "Zufällige 40 Bits", "correct": true, "because": "Macht sie unik"}, {"text": "Globale Routbarkeit", "correct": false, "because": "Nicht gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass FC00::/7 wie IPv4s 192.168 ist. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Beides für private Netze"}, {"text": "Nein", "correct": false, "because": "Ähnlich, aber größerer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Unique Local-Adresse?', 3, '[{"text": "Lokale Eindeutigkeit", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Globale Erreichbarkeit", "correct": false, "because": "Nicht der Zweck"}, {"text": "Kürzeste Darstellung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FD00::/8 ist zufällig. b) FC00::/7 ist routbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nicht routbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet FC00::/7?', 5, '[{"text": "Private Nutzung", "correct": true, "because": "Nicht öffentlich routbar"}, {"text": "Eindeutigkeit lokal", "correct": true, "because": "Zufällige ID"}, {"text": "Globale Erreichbarkeit", "correct": false, "because": "Nicht der Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei FC00::/7 unwichtig?', 3, '[{"text": "Präfix FC00", "correct": false, "because": "Definiert Typ"}, {"text": "Zufällige Bits", "correct": false, "because": "Sichert Eindeutigkeit"}, {"text": "Internet-Routing", "correct": true, "because": "Nur privat"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann FC00::/7 über Router gehen?', 2, '[{"text": "Nein", "correct": true, "because": "Nicht global routbar"}, {"text": "Ja", "correct": false, "because": "Nur lokal nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob FD00::/8 für öffentliche Netze ist?', 3, '[{"text": "Nein", "correct": true, "because": "Für private Netze"}, {"text": "Ja", "correct": false, "because": "Nicht routbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix wähle ich für ein nicht routbares Netz?', 4, '[{"text": "FC00::/7", "correct": true, "because": "Unique Local"}, {"text": "2000::/3", "correct": false, "because": "Global Unicast"}, {"text": "FE80::/10", "correct": false, "because": "Link-Local"}]');
